        return resolveIdempotent(existing.get(), req); // match → return; mismatch → throw IDEMPOTENCY_CONFLICT (record rejection)
    }
    try {
        return self.issue(req, now);  // @Transactional
    } catch (DuplicateKeyException e) {
        BridgePermit raced = repo.findByRequestId(req.requestId()).orElseThrow(...);
