public BridgePermit confirmEntry(long permitId, String opRequestId) {
    Instant now = clock.instant();
    BridgePermit permit = repo.findById(permitId).orElseThrow(notFound);
    // fast-path replay
    if (permit.status() == ENTERED) {
        if (opRequestId.equals(permit.entryRequestId())) return permit;
        throw new PermitConflictException("IDEMPOTENCY_CONFLICT", "进桥请求键与已记录不一致");
    }
    if (permit.status() != APPROVED) throw conflict INVALID_STATE;
    if (now.isBefore(permit.windowStartAt()) || !now.isBefore(permit.windowEndAt()))
        throw conflict OUTSIDE_WINDOW;
    int updated = repo.markEntered(permitId, now, opRequestId, now);
    if (updated == 0) {
        // lost race with cancel or another entry
        BridgePermit current = repo.findById(permitId).orElseThrow();
        if (current.status() == ENTERED && opRequestId.equals(current.entryRequestId())) return current;
        if (current.status() == ENTERED) throw IDEMPOTENCY_CONFLICT;
        if (current.status() == CANCELLED) throw conflict PERMIT_CANCELLED "许可已撤销，不得进桥";
        throw INVALID_STATE;
    }
    return repo.findById(permitId).orElseThrow();
}
