    private <T> List<Outcome<T>> runConcurrently(Callable<T> first, Callable<T> second) throws Exception {
        CountDownLatch gate = new CountDownLatch(1);
        Callable<T> gatedFirst = () -> {
            gate.await();
            return first.call();
        };
        Callable<T> gatedSecond = () -> {
            gate.await();
            return second.call();
        };
